SELECT SUM("Generico_5"."InversionUS") AS "sum_InversionUS_ok",   CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Generico_5" WHERE ((CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) <= 2015) AND ("Generico_5"."Anunciante" IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) IN (1, 2, 3, 4, 5))) GROUP BY "yr_FECHA_ok";
